"""policy.ini (docs/policy.md)."""

import re
from dataclasses import dataclass
from datetime import timedelta, timezone

from logkeep import streams
from logkeep.errors import DataError


@dataclass(frozen=True)
class Policy:
    max_size: object = None      # bytes or None
    max_age: object = None       # timedelta or None
    naming: str = "numbered"
    offset: timezone = timezone.utc
    compress_after: int = 1
    keep: int = 5
    keep_days: object = None     # int or None


def _bad(msg):
    raise DataError("policy", msg)


def _size(v):
    m = re.fullmatch(r"([0-9]+)([KkMmGg]?)", v)
    if not m:
        _bad(f"bad size {v!r}")
    return int(m.group(1)) * {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}[m.group(2).lower()]


def _dur(v):
    m = re.fullmatch(r"([0-9]+)([mhd])", v)
    if not m:
        _bad(f"bad duration {v!r}")
    unit = {"m": "minutes", "h": "hours", "d": "days"}[m.group(2)]
    return timedelta(**{unit: int(m.group(1))})


def _off(f):
    return lambda v: None if v == "off" else f(v)


def _naming(v):
    if v not in ("numbered", "dated"):
        _bad(f"bad naming {v!r}")
    return v


def _offset(v):
    m = re.fullmatch(r"([+-])([0-9]{2}):([0-9]{2})", v)
    if not m or int(m.group(2)) > 23 or int(m.group(3)) > 59:
        _bad(f"bad offset {v!r}")
    d = timedelta(hours=int(m.group(2)), minutes=int(m.group(3)))
    return timezone(-d if m.group(1) == "-" else d)


def _num(minimum):
    def f(v):
        if not re.fullmatch(r"[0-9]+", v) or int(v) < minimum:
            _bad(f"bad number {v!r}")
        return int(v)
    return f


KEYS = {
    "max_size": _off(_size),
    "max_age": _off(_dur),
    "naming": _naming,
    "offset": _offset,
    "compress_after": _num(0),
    "keep": _num(1),
    "keep_days": _off(_num(1)),
}


def load(path):
    """Returns (defaults dict, {stream: dict}) of parsed values."""
    if not path.exists():
        return {}, {}
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise DataError("policy", f"{path.name}: {e}") from None
    sections = {}
    current = None
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line[0] in "#;":
            continue
        if line.startswith("["):
            if not line.endswith("]"):
                _bad(f"bad line {raw!r}")
            title = line[1:-1]
            if title == "defaults":
                key = ("defaults", None)
            elif title.startswith("stream ") and streams.valid(title[7:]):
                key = ("stream", title[7:])
            else:
                _bad(f"bad section {title!r}")
            if key in sections:
                _bad(f"section {title!r} twice")
            sections[key] = current = {}
            continue
        if current is None or "=" not in line:
            _bad(f"bad line {raw!r}")
        k, v = (s.strip() for s in line.split("=", 1))
        if k not in KEYS:
            _bad(f"unknown key {k!r}")
        if k in current:
            _bad(f"key {k!r} twice")
        current[k] = KEYS[k](v)
    defaults = sections.get(("defaults", None), {})
    per = {k[1]: v for k, v in sections.items() if k[0] == "stream"}
    return defaults, per


def for_stream(loaded, name):
    defaults, per = loaded
    vals = dict(defaults)
    vals.update(per.get(name, {}))
    return Policy(**vals)
