"""rotate (docs/rotate.md)."""

import gzip
import os
import re
from datetime import date, datetime, timedelta, timezone

from logkeep import dates, policy, state, streams
from logkeep.errors import DataError, Refused

LEGACY = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}")


def parse_time(text):
    """A time of data.md section 2 as an aware datetime, or None."""
    if not isinstance(text, str):
        return None
    try:
        if LEGACY.fullmatch(text):
            return datetime.fromisoformat(text).replace(tzinfo=timezone.utc)
        t = datetime.fromisoformat(text)
    except ValueError:
        return None
    return t if t.tzinfo is not None and t.utcoffset() is not None else None


class Arch:
    def __init__(self, name, key, gz, new=False):
        self.name, self.key, self.gz, self.new = name, key, gz, new
        self.time = None
        self.final = None
        self.compress = False


def find_archives(ctx, name, naming):
    d = streams.logs_dir(ctx.data)
    out = []
    if not d.is_dir():
        return out
    base = re.escape(name) + r"\.log\."
    if naming == "numbered":
        rx = re.compile(base + r"([1-9][0-9]*)(\.gz)?")
    else:
        rx = re.compile(base + r"([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?")
    seen = {}
    for p in sorted(d.iterdir(), key=lambda p: p.name):
        m = rx.fullmatch(p.name)
        if not m or not p.is_file():
            continue
        if naming == "numbered":
            key = (-int(m.group(1)),)
            gz = bool(m.group(2))
        else:
            try:
                day = date.fromisoformat(m.group(1))
            except ValueError:
                continue
            key = (day.toordinal(), int(m.group(2) or 1))
            gz = bool(m.group(3))
        if key in seen:
            raise DataError("archives", f"{seen[key]} and {p.name} are in the same place")
        seen[key] = p.name
        out.append(Arch(p.name, key, gz))
    out.sort(key=lambda a: a.key, reverse=True)
    return out


def validate_state(ctx, existing):
    for name in existing:
        e = ctx.state["streams"].get(name)
        if e is None:
            continue
        if "opened" in e and parse_time(e["opened"]) is None:
            raise DataError("state", f"{name}: bad opened")
        if "archives" in e:
            a = e["archives"]
            if not isinstance(a, dict):
                raise DataError("state", f"{name}: archives is not an object")
            for k, v in a.items():
                if parse_time(v) is None:
                    raise DataError("state", f"{name}: bad time for {k}")
        if "rotations" in e:
            r = e["rotations"]
            if not isinstance(r, int) or isinstance(r, bool) or r < 0:
                raise DataError("state", f"{name}: bad rotations")


def first_time(path):
    try:
        with path.open("rb") as f:
            line = f.readline()
    except OSError:
        return None
    line = line.rstrip(b"\r\n")
    word = line.split(b" ", 1)[0]
    try:
        return parse_time(word.decode("utf-8"))
    except UnicodeDecodeError:
        return None


def final_name(stream, a, pos, naming, gz):
    if naming == "numbered":
        return f"{stream}.log.{pos}" + (".gz" if gz else "")
    base = a.name[:-3] if a.name.endswith(".gz") else a.name
    return base + (".gz" if gz else "")


def plan_stream(ctx, name, pol, force, exists_log, entry):
    log = streams.log_path(ctx.data, name)
    archives = find_archives(ctx, name, pol.naming)
    return dict(name=name, pol=pol, log=log, archives=archives, entry=entry)


def decide(ctx, p, force):
    pol, log, entry = p["pol"], p["log"], p["entry"]
    if not log.is_file():
        return None, "no log"
    size = log.stat().st_size
    if size == 0:
        return None, "empty"
    if force:
        return "forced", "rotate (forced)"
    if pol.max_size is not None and size >= pol.max_size:
        return "size", "rotate (size)"
    if pol.max_age is not None:
        opened = parse_time(entry["opened"]) if "opened" in entry else first_time(log)
        if opened is not None and ctx.now - opened >= pol.max_age:
            return "age", "rotate (age)"
    return None, "not due"


def run(ctx, names_arg, dry, force):
    loaded = policy.load(ctx.policy_path)
    ctx.state  # loads and checks the file
    existing = set(streams.active(ctx.data)) | set(loaded[1])
    validate_state(ctx, existing)
    if names_arg:
        for n in names_arg:
            if n not in existing:
                raise Refused("unknown-stream", f"no stream {n}")
        names = sorted(set(names_arg))
    else:
        names = sorted(existing)
    plans = []
    for n in names:
        pol = policy.for_stream(loaded, n)
        entry = ctx.state["streams"].get(n, {})
        plans.append(plan_stream(ctx, n, pol, force, None, entry))

    out, ops = [], []
    n_rot = n_rem = n_comp = 0
    new_entries = {}
    for p in plans:
        name, pol, entry = p["name"], p["pol"], p["entry"]
        reason, what = decide(ctx, p, force)
        rotated = reason is not None
        out.append(f"{name}: {what}")
        times = entry.get("archives", {}) if isinstance(entry.get("archives", {}), dict) else {}
        archs = p["archives"]
        for a in archs:
            t = times.get(a.name)
            a.time = parse_time(t) if t is not None else None
            a.rawtime = t
        newa = None
        if rotated:
            n_rot += 1
            if pol.naming == "numbered":
                newa = Arch(f"{name}.log.1", (1,), False, True)
                for a in archs:
                    a.key = (a.key[0] - 1,)
                newa.key = (-1,)
                # shifting keeps order; new is newest
            else:
                day = ctx.now.astimezone(pol.offset).date()
                ks = [a.key[1] for a in archs if a.key[0] == day.toordinal()]
                k = max(ks) + 1 if ks else None
                nm = f"{name}.log.{day.isoformat()}" + (f".{k}" if k else "")
                newa = Arch(nm, (day.toordinal(), k or 1), False, True)
            newa.time = ctx.now
            newa.rawtime = dates.stamp(ctx.now)
            archs = sorted(archs + [newa], key=lambda a: a.key, reverse=True)
        keep_pairs = []
        removed = []
        for pos, a in enumerate(archs, 1):
            drop = pos > pol.keep
            if (not drop and pol.keep_days is not None and a.time is not None
                    and ctx.now - a.time >= timedelta(days=pol.keep_days)):
                drop = True
            (removed if drop else keep_pairs).append(a)
        lines = []
        remaining = []
        for pos, a in enumerate(keep_pairs, 1):
            gz = a.gz
            if pos > pol.compress_after and not a.gz:
                gz = True
                a.compress = True
                n_comp += 1
            a.final = final_name(name, a, pos, pol.naming, gz)
            remaining.append(a)
            if a.new:
                lines.append(f"  new {a.final}")
            elif a.final != a.name:
                lines.append(f"  {a.final} <- {a.name}")
            else:
                lines.append(f"  {a.name}")
        out.extend(lines)
        for a in removed:
            out.append(f"  remove {a.name}")
            n_rem += 1
        ops.append((p, newa, remaining, removed, rotated))
        ne = {}
        if rotated:
            ne["opened"] = dates.stamp(ctx.now)
        elif "opened" in entry:
            ne["opened"] = entry["opened"]
        ne["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
        ne["archives"] = {a.final: a.rawtime for a in remaining if a.rawtime is not None}
        new_entries[name] = ne
    out.append(f"{n_rot} rotated, {n_rem} removed, {n_comp} compressed")
    if dry:
        out.append("dry run: nothing written")
        return out

    d = streams.logs_dir(ctx.data)
    tmp = []

    def stage(src_bytes, i):
        t = d / f".logkeep-tmp-{len(tmp)}"
        t.write_bytes(src_bytes)
        tmp.append(t)
        return t

    moves = []  # (tmp path, final path)
    for p, newa, remaining, removed, rotated in ops:
        if rotated:
            data = p["log"].read_bytes()
            if newa in remaining:
                if newa.compress:
                    data = gzip.compress(data, mtime=0)
                moves.append((stage(data, 0), d / newa.final))
            p["log"].write_bytes(b"")
        for a in removed:
            if not a.new:
                os.remove(d / a.name)
        for a in remaining:
            if a.new or (a.final == a.name):
                continue
            src = d / a.name
            if a.compress:
                data = gzip.compress(src.read_bytes(), mtime=0)
                os.remove(src)
                moves.append((stage(data, 0), d / a.final))
            else:
                t = d / f".logkeep-tmp-{len(tmp)}"
                os.replace(src, t)
                tmp.append(t)
                moves.append((t, d / a.final))
    for t, f in moves:
        os.replace(t, f)
    ctx.state["streams"].update(new_entries)
    state.save(ctx.state_path, ctx.state)
    return out
